import pandas as pd
import matplotlib.pyplot as plt
import seaborn as sns
import base64
from io import BytesIO
import re
from collections import Counter
import os

# Set output path
output_dir = '/app/output'
os.makedirs(output_dir, exist_ok=True)
output_path = os.path.join(output_dir, 'final_report.html')

# 1. Load Data
df = pd.read_csv('/app/benchmark/data.csv')

# 2. Compute KPIs
total_questions = len(df)
years_count = df['year'].nunique()
year_min = df['year'].min()
year_max = df['year'].max()

# Type counts
overall_type_counts = df['type'].value_counts()
type_ratios = (overall_type_counts / total_questions * 100).round(1).to_dict()

# Yearly data
yearly_counts = df.groupby(['year', 'type']).size().unstack(fill_value=0)
yearly_totals = df.groupby('year').size()
yearly_change = yearly_totals.diff().fillna(0)
yearly_pct_change = yearly_totals.pct_change().fillna(0) * 100

avg_questions_per_year = round(total_questions / years_count, 1)

# 3. Text Analysis for Topics
stop_words = {
    'the', 'is', 'a', 'in', 'of', 'and', 'to', 'for', 'which', 'are', 'by', 'an', 
    'what', 'on', 'with', 'from', 'it', 'as', 'that', 'this', 'be', 'or', 'can', 
    'has', 'have', 'not', 'do', 'does', 'did', 'used', 'using', 'use', 'explain', 
    'describe', 'define', 'write', 'how', 'why', 'give', 'any', 'two', 'three', 
    'four', 'one', 'all', 'these', 'following', 'called', 'known', 'when', 'where', 
    'who', 'statement', 'program', 'function', 'system', 'data', 'computer', 'science',
    'between', 'differentiate', 'different', 'types', 'type', 'example', 'examples', 'b', 'c'
}

def extract_keywords(text):
    text = str(text).replace('$', ' ').lower()
    text = re.sub(r'[^a-z\s]', ' ', text)
    words = text.split()
    return [w for w in words if w not in stop_words and len(w) > 2]

all_keywords = []
for q in df['question']:
    all_keywords.extend(extract_keywords(q))

keyword_counts = Counter(all_keywords).most_common(20)

# 4. Generate Visualizations
def plot_to_base64(plt_obj):
    buf = BytesIO()
    plt_obj.savefig(buf, format='png', bbox_inches='tight', dpi=120)
    plt_obj.close()
    return base64.b64encode(buf.getvalue()).decode('utf-8')

sns.set_theme(style="whitegrid")

# Chart 1: Total Questions per Year
plt.figure(figsize=(10, 5))
ax = sns.barplot(x=yearly_totals.index, y=yearly_totals.values, hue=yearly_totals.index, palette='Blues_d', legend=False)
plt.title('Total Questions per Year (2015-2025)', fontsize=14)
plt.xlabel('Year')
plt.ylabel('Number of Questions')
for i, v in enumerate(yearly_totals.values):
    ax.text(i, v + 0.5, str(v), ha='center')
chart_yearly_volume = plot_to_base64(plt)

# Chart 2: Question Type Breakdown per Year
yearly_counts.plot(kind='bar', stacked=True, figsize=(10, 6), colormap='viridis')
plt.title('Question Type Composition & Trends per Year', fontsize=14)
plt.xlabel('Year')
plt.ylabel('Number of Questions')
plt.legend(title='Question Type', bbox_to_anchor=(1.05, 1), loc='upper left')
plt.xticks(rotation=0)
chart_yearly_types = plot_to_base64(plt)

# Chart 3: Overall Question Type Ratio
plt.figure(figsize=(7, 7))
plt.pie(overall_type_counts, labels=overall_type_counts.index, autopct='%1.1f%%', startangle=140, colors=sns.color_palette("pastel"))
plt.title('Overall Question Type Ratio (2015-2025)', fontsize=14)
chart_overall_types = plot_to_base64(plt)

# Chart 4: Top Keywords
kw_df = pd.DataFrame(keyword_counts, columns=['Keyword', 'Frequency'])
plt.figure(figsize=(10, 7))
sns.barplot(data=kw_df, x='Frequency', y='Keyword', hue='Keyword', palette='mako', legend=False)
plt.title('Top 20 Recurring Keywords/Topics in Exam Questions', fontsize=14)
plt.xlabel('Frequency')
plt.ylabel('Keyword / Topic')
chart_keywords = plot_to_base64(plt)

# Compute Yearly Data Table HTML
yearly_summary_df = pd.DataFrame({
    'Total Questions': yearly_totals,
    'YoY Change': yearly_change,
    'YoY % Change': yearly_pct_change.round(1).astype(str) + '%'
}).join(yearly_counts)

yearly_summary_df.index.name = 'Year'
yearly_table_html = yearly_summary_df.to_html(classes='data-table')

